S = {'cc': 'SI', 'fam': 'Social', 'doc': '# SI 2025: employer social contributions (2200) and payroll taxes (3000)\n\nSource: Finančna uprava RS (FURS), brochure "Prispevki za socialno varnost" (2025 edition, with the long-term-care contribution from 1 July 2025), `cmp20/central/si/refs/fu_Brosura_prispevki.doc` (kept by the 1.x model), section 2.2 table.\n* 2.2 Vrste in stopnje prispevkov (delavci v delovnem razmerju), Stopnja prispevka delodajalca: "za pokojninsko in invalidsko zavarovanje 8,85 %; za zdravstveno zavarovanje 6,56 %; za dolgotrajno oskrbo** 1,00 %; za starševsko varstvo 0,10 %; za primer brezposelnosti 0,06 %; za poškodbe pri delu in poklicne bolezni 0,53 %; Skupaj 17,10 %"\n* "**Prispevek se plačuje za obdobje od 1. julija 2025 dalje."\n', 'lean': 'def c0 : Contribution := { name := "Prispevek za pokojninsko in invalidsko zavarovanje (delodajalec)", sched := Schedule.flat 885, ceiling := -1 }\ndef c1 : Contribution := { name := "Prispevek za zdravstveno zavarovanje (delodajalec)", sched := Schedule.flat 656, ceiling := -1 }\ndef c2 : Contribution := { name := "Prispevek za poškodbe pri delu in poklicne bolezni", sched := Schedule.flat 53, ceiling := -1 }\ndef c3 : Contribution := { name := "Prispevek za starševsko varstvo (delodajalec)", sched := Schedule.flat 10, ceiling := -1 }\ndef c4 : Contribution := { name := "Prispevek za primer brezposelnosti (delodajalec)", sched := Schedule.flat 6, ceiling := -1 }\ndef c5 : Contribution := { name := "Prispevek za dolgotrajno oskrbo (delodajalec, od 1. 7. 2025)", sched := Schedule.flat 50, ceiling := -1 }\n\ndef contribs : List (Contribution × Oecd × String) :=\n  [(c0, .sscEmployer, "FURS 2025: 8,85 % (ZPIZ-2)"),\n   (c1, .sscEmployer, "FURS 2025: 6,56 % (ZZVZZ)"),\n   (c2, .sscEmployer, "FURS 2025: 0,53 % (ZZVZZ)"),\n   (c3, .sscEmployer, "FURS 2025: 0,10 %"),\n   (c4, .sscEmployer, "FURS 2025: 0,06 %"),\n   (c5, .sscEmployer, "ZDOsk-1; FURS 2025: 1,00 % od 1. julija 2025 (6 of 12 months: 0,50 % of the year\'s pay)")]\n\n/-- On the household\'s wages: each adult, each contribution (borne by the employer). -/\ndef householdCharges (g : CanonGlobal) : List Charge :=\n  if g.entity == .company then [] else\n  (g.household.adults.zipIdx.filter (fun (a, _) => 0 < a.wages)).flatMap fun (a, i) =>\n    contribs.map fun (c, o, st) =>\n      charge o c.name a.wages id (fun x => c.amount x) (event := s!"adult {i + 1}") (level := .social)\n        (bearer := .employer) (statute := st)\n\n/-- On a company\'s payroll, spread evenly over its employees (ceilings per employee). -/\ndef companyCharges (g : CanonGlobal) : List Charge :=\n  if g.entity != .company || g.company.payroll ≤ 0 then [] else\n  let n : Int := max 1 (g.company.employees : Int)\n  let avg := g.company.payroll / n\n  contribs.map fun (c, o, st) =>\n    charge o c.name g.company.payroll id (fun _ => n * c.amount avg) (event := "payroll") (level := .social)\n      (statute := st)\n', 'families': [('2200/3000 employer contributions', ['.sscEmployer'], 'householdCharges g ++ companyCharges g')], 'notes': ['SI 2200/3000: FURS brochure, 2025 (long-term care from 1.7.2025)'], 'unsupported': [('g.household.adults.any (fun a => 0 < a.wages)', "the minimum contribution base (60 % of the average wage) not applied; long-term care taken as 1 % on half the year's pay (evenly paid)"), ('g.entity == .company && g.company.payroll > 0', 'company payroll spread evenly over its employees (per-employee ceilings applied to the average wage)')], 'guards': ['c0.amount 50000 == 4425', 'c0.amount 200000 == 17700', 'c1.amount 50000 == 3280', 'c1.amount 200000 == 13120', 'c2.amount 50000 == 265', 'c2.amount 200000 == 1060', 'c3.amount 50000 == 50', 'c3.amount 200000 == 200', 'c4.amount 50000 == 30', 'c4.amount 200000 == 120', 'c5.amount 50000 == 250', 'c5.amount 200000 == 1000'], 'taxes': [{'oecd': '2200', 'tax': 'Prispevek za pokojninsko in invalidsko zavarovanje (delodajalec)', 'statute': 'FURS 2025: 8,85 % (ZPIZ-2)', 'dated': 'FURS brochure, 2025 (long-term care from 1.7.2025)', 'grade': 'B', 'kernel_parts': ['Contribution'], 'unsupported': []}, {'oecd': '2200', 'tax': 'Prispevek za zdravstveno zavarovanje (delodajalec)', 'statute': 'FURS 2025: 6,56 % (ZZVZZ)', 'dated': 'FURS brochure, 2025 (long-term care from 1.7.2025)', 'grade': 'B', 'kernel_parts': ['Contribution'], 'unsupported': []}, {'oecd': '2200', 'tax': 'Prispevek za poškodbe pri delu in poklicne bolezni', 'statute': 'FURS 2025: 0,53 % (ZZVZZ)', 'dated': 'FURS brochure, 2025 (long-term care from 1.7.2025)', 'grade': 'B', 'kernel_parts': ['Contribution'], 'unsupported': []}, {'oecd': '2200', 'tax': 'Prispevek za starševsko varstvo (delodajalec)', 'statute': 'FURS 2025: 0,10 %', 'dated': 'FURS brochure, 2025 (long-term care from 1.7.2025)', 'grade': 'B', 'kernel_parts': ['Contribution'], 'unsupported': []}, {'oecd': '2200', 'tax': 'Prispevek za primer brezposelnosti (delodajalec)', 'statute': 'FURS 2025: 0,06 %', 'dated': 'FURS brochure, 2025 (long-term care from 1.7.2025)', 'grade': 'B', 'kernel_parts': ['Contribution'], 'unsupported': []}, {'oecd': '2200', 'tax': 'Prispevek za dolgotrajno oskrbo (delodajalec, od 1. 7. 2025)', 'statute': "ZDOsk-1; FURS 2025: 1,00 % od 1. julija 2025 (6 of 12 months: 0,50 % of the year's pay)", 'dated': 'FURS brochure, 2025 (long-term care from 1.7.2025)', 'grade': 'B', 'kernel_parts': ['Contribution'], 'unsupported': []}]}
